                Unit
            }
            is FfiComposerContextInput.GitDiff -> {
                buf.putInt(4)
                FfiConverterBoolean.write(value.`staged`, buf)
                FfiConverterString.write(value.`label`, buf)
                FfiConverterOptionalString.write(value.`diffText`, buf)
